catalog_script_client.script:
function onSubmit() {

	var total=0, jan=0, feb=0, mar=0, apr=0, may=0, jun=0, jul=0, aug=0, sep=0, oct=0, nov=0, dec=0;
    jan = parseInt(g_form.getValue('ohs_mtgs_january'));
    feb = parseInt(g_form.getValue('ohs_mtgs_february'));
    mar = parseInt(g_form.getValue('ohs_mtgs_march'));
    apr = parseInt(g_form.getValue('ohs_mtgs_april'));
    may = parseInt(g_form.getValue('ohs_mtgs_may'));
    jun = parseInt(g_form.getValue('ohs_mtgs_june'));
    jul = parseInt(g_form.getValue('ohs_mtgs_july'));
    aug = parseInt(g_form.getValue('ohs_mtgs_august'));
    sep = parseInt(g_form.getValue('ohs_mtgs_september'));
    oct = parseInt(g_form.getValue('ohs_mtgs_october'));
    nov = parseInt(g_form.getValue('ohs_mtgs_november'));
    dec = parseInt(g_form.getValue('ohs_mtgs_december'));
	total = jan + feb + mar + apr + may + jun + jul + aug + sep + oct + nov + dec;

    g_form.setValue('ohs_mtg_total', total);
}
